// === Tab: mySketch.js ===
/*
It is a 3D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Eroded".

This is a 3D shader that represents a sunken artifact of human
civilization, rusted and eroded.
*/

let theShader, dpr = Math.max(1, 0.5 * window.devicePixelRatio), ww = window.innerWidth*dpr, wh = window.innerHeight*dpr, startRandom;
const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(ww, wh);
	const canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2587630/files/vert.glsl', 'frag.glsl');
}

function setup() {
  pixelDensity(1);
  createCanvas(ww, wh, WEBGL);
	var canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
	startRandom = Math.random();
}

function draw() {
  // shader() sets the active shader with our shader
  shader(theShader);

  // here we're using setUniform() to send our uniform values to the shader
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);

  // rect gives us some geometry on the screen
  rect(0,0,width,height);
}

// Override to enable webgl2 and support for high resolution and retina displays
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext;
			gl.viewport(0, 0, ww, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define MN min(R.x,R.y)
#define N normalize
#define S smoothstep
#define SE(v,s,k) S(s+k/MN,s-k/MN,v)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
float noise(vec2 p) {
	vec2 i=floor(p), f=fract(p), u=f*f*(3.-2.*f), k=vec2(1,0);
	float
	a=rnd(i),
	b=rnd(i+k),
	c=rnd(i+k.yx),
	d=rnd(i+1.);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
float fbm(vec2 p, mat2 m) {
	float t=.0, a=1., h=.0;
	for (float i=.0; i<4.; i++) {
		t+=a*noise(p);
		p*=2.*m;
		a*=.5;
		h+=a;
	}
	return t/h;
}
float smin(float a, float b, float k) {
	float h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
vec2 pmod(vec2 p, float n) {
	float
	a=atan(p.x,p.y)+3.14159/n,
	b=6.28318/n;
	a=floor(a/b)*b;
	return rot(-a)*p;
}
float ftor(vec3 p, vec2 s) {
	p.y-=clamp(round(p.y*.5),-1.,1.)/.5;
	vec2 c=vec2(length(p.xz)-s.x,p.y);
	c=abs(c)-s.y;
	return length(max(c,.0))+min(.0,max(c.x,c.y));
}
float box(vec3 p, vec3 s) {
	p=abs(p)-s;
	return length(max(p,.0))+min(.0,max(max(p.x,p.y),p.z));
}
#define LVL 10.
float mat=.0;
float map(vec3 p) {
	mat=.0;
	if (p.y>LVL) return -(p.y-LVL); //water
	float,
	t=fbm(vec2(10,-20)+p.xz*3e-2,mat2(1,-.5,1,.5))*5.+1.,
	terrain=p.y+t+.2*(cos(p.x*.1)+sin(p.z*.5)),
	stones=box(p+vec3(-17,6,5),vec3(18,2,2))-.05;
	vec3 q=p;
	p.xy*=rot(-.42);
	p.y+=8.;
	float d=5e5,
	artefc=length(pmod(p.xz+vec2(-20,20),8.)-vec2(0,10))-.5;
	artefc=min(artefc,ftor(p+vec3(-20,1,20),vec2(10,.5)));
	artefc=max(artefc,(p.y-5.));
	artefc=smin(artefc,-(box(p+vec3(-14,1,20),vec3(6,14,6))),-noise(p.yy*12.));
	d=min(d,stones);
	d=min(d,artefc);
	d=min(d,terrain);
	if (d==min(artefc,-(q.y-10.)) || d==min(stones,-(q.y-9.))) mat=1.;
	return d;
}
vec3 norm(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1);
	return N(
		k.xyy*map(p+k.xyy*h)+
		k.yxy*map(p+k.yxy*h)+
		k.yyx*map(p+k.yyx*h)+
		k.xxx*map(p+k.xxx*h)
	);
}
float caustic(vec3 p) {
	float
	t=-T, size=.2,
	v1=fbm(p.xz*size+t*vec2(1,0),mat2(1)),
	v2=noise(v1+4.*p.xz*size*.7+t*vec2(.2,.6)),
	v=abs(v1-sqrt(v2));
	return 1.-clamp((v-.05)*60.,.0,1.);
}
void cam(inout vec3 p) {
	p.yz*=rot(-.2);
	p.xz*=rot(4.*mix(.0,1.,S(-1.,1.,T*.1)));
}
float rnd(float a) {
	vec2 p=fract(a*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
float curve(float t, float e) {
	t/=e;
	return mix(
		rnd(floor(t)),
		rnd(floor(t)+1.),
		pow(S(.0,1.,fract(t)),10.)
	);
}
float logo(vec2 p, float k) {
	p*=k;
	p*=rot(-1.57+3.1415*curve(T,.4));
	vec2 q=p;
	q.x=abs(abs(q.x)-.2);
	q.y+=q.x-.2;
	float d=.0;
	d+=SE(length(q),.1,k);
	d=max(d,SE(abs(length(p)-.225)-.025,.0,k));
	return d;
}
float placeLogo() {
	vec2 p=FC/R;
	p*=vec2(R.x/R.y,1);
	p-=vec2(R.x/R.y,0);
	p+=vec2(.075,-.05);
	return logo(p,24.);
}
void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(.05,.1,.2),
	p=vec3(0,5,-15),
	rd=N(vec3(uv,1)),
	vp=p;
	cam(p); cam(rd);
	const float maxd=80.;
	float dd=.0;
	for (float i=.0; i<80.; i++) {
		float d=map(p)*mix(.75,1.,rnd(p.xy));
		if (abs(d)<1e-3) break;
		if (d>maxd) break;
		p+=rd*d;
		dd+=d;
	}
	vec3 n=norm(p), lp=vec3(1,4.+sin(T)*.2,-1), l=N(lp), cl=vec3(lp.x,0,lp.z);
	float causg=1.-caustic(p+cl*(p.y/-lp.y)), dif=p.y>LVL-5e-3?1.-causg:causg;
	var float steps=15.;
	float sum=.0;
	vec3 vr=rd*maxd/400.;
	vp+=mix(.05,1.,rnd(uv))*vr;
	for (float i=.0; i<steps; i++) {
		sum+=clamp(caustic(vp+cl*(vp.y/-lp.y))*100.,.0,1.);
		vp+=vr;
	}
	col*=1.-causg;
	col*=mix(p.y<LVL-5E-3?.25:.2,1.,S(4.,.0,.125*length(lp.xz-p.xz)))*vec3(4,6,9);
	col=max(vec3(.05,.1,.2),col);
	col+=.25*pow(clamp(dot(reflect(rd,n),p.y<LVL-5e-3?l:N(lp-p)),.0,1.),5.2);
	if (mat>.0) {
		col*=mix(vec3(1,.05,.05),vec3(.2,.5,.3),clamp(p.y+8.,.0,1.)*mix(.0,1.,rnd(p.xz)));
	}
	col=mix(vec3(.025,.05,.1),col,exp(-125e-8*dd*dd*dd));
	col+=sum*.45/steps;
	col*=S(.0,1.,T*.1);
	col=clamp(col+.25*placeLogo(),.08,1.);
	O=vec4(col,1);
}

